#include <cstddef> // for size_t
#include <cstdint> // for uintptr_t

struct block {
    void* ptr;
    size_t length;
    explicit operator bool() const { return ptr != nullptr; }
};

block allocate(char*& p, const char* data, size_t max_size, size_t alignment, size_t n) {
    // Calculate the aligned address
    uintptr_t raw_address = reinterpret_cast<uintptr_t>(p);
    uintptr_t aligned_address = (raw_address + alignment - 1) & ~(alignment - 1);

    // Check if the aligned block fits in the buffer
    if (aligned_address + n > reinterpret_cast<uintptr_t>(data) + max_size) {
        return {nullptr, 0};
    }

    // Update the stack pointer and return the block
    p = reinterpret_cast<char*>(aligned_address + n);
    return {reinterpret_cast<void*>(aligned_address), n};
}

#include <cstddef> // for size_t
#include <cstdint> // for uintptr_t

namespace alb {
    struct block {
        void* ptr;
        size_t length;
        explicit operator bool() const { return ptr != nullptr; }
    };
}

namespace alb::stack_allocator_impl {
    block allocate(char*& p, const char* data, size_t max_size, size_t alignment, size_t n) {
        // Handle zero-size allocation
        if (n == 0) {
            return {nullptr, 0};
        }

        // Handle zero alignment (treat as 1)
        if (alignment == 0) {
            alignment = 1;
        }

        // Ensure alignment is a power of two
        if ((alignment & (alignment - 1)) != 0) {
            return {nullptr, 0};
        }

        // Calculate the aligned address
        uintptr_t raw_address = reinterpret_cast<uintptr_t>(p);
        uintptr_t aligned_address = (raw_address + alignment - 1) & ~(alignment - 1);

        // Check if the aligned block fits in the buffer
        if (aligned_address + n > reinterpret_cast<uintptr_t>(data) + max_size) {
            return {nullptr, 0};
        }

        // Update the stack pointer and return the block
        p = reinterpret_cast<char*>(aligned_address + n);
        return {reinterpret_cast<void*>(aligned_address), n};
    }
}

